const ALIAS={hp:'device',phone:'device',iphone:'device',ipad:'device',perangkat:'device',kuat:'compatibility',support:'compatibility',supported:'compatibility',cocok:'compatibility',ram:'memory',memori:'memory',memory:'memory',panas:'thermal',hot:'thermal',lag:'performance',ngelag:'performance',stutter:'performance',patah:'performance',fps:'performance',crash:'crash',ngecrash:'crash',keluar:'crash',freeze:'freeze',macet:'freeze',hang:'freeze',error:'troubleshooting',masalah:'problem',problem:'problem',launcher:'launcher',ipa:'install',sideload:'install',pasang:'install',install:'install',update:'updates',versi:'build',version:'build',build:'build',mod:'mods',mods:'mods',savegame:'save',saves:'save',controller:'controls',gamepad:'controls',joystick:'controls',touch:'controls',suara:'audio',sound:'audio',storage:'storage',penyimpanan:'storage',setting:'settings',settings:'settings',grafik:'graphics',graphics:'graphics',resolusi:'resolution',resolution:'resolution',bayangan:'shadows',shadow:'shadows',metalfx:'metalfx',msaa:'msaa',log:'logs',logs:'logs',online:'multiplayer',wifi:'network',jaringan:'network'};
const norm=v=>String(v||'').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[’']/g,'').replace(/gta\s*5/g,'gta v').replace(/[^a-z0-9+._-]+/g,' ').replace(/\s+/g,' ').trim();
