function pick(kind){const list=SOCIAL[kind];if(!list?.length)return null;return list[(state.socialTurn++)%list.length];}
function social(q){const n=norm(q);if(!n||n.length>180||/[\r\n]/.test(String(q)))return null;if(/^(p|tes|test|testing|cek|check|ping|hello test|test franklin)$/.test(n))return{text:pick('test'),topic:'small-talk',grounded:true};if(/^(hi|hey|hello|hallo|halo|hai|hei|yo|oi|woy|sup|wassup|whats up|what s up)( there)?( franklin| bro| bang| kak| homie)?$/.test(n))return{text:pick('greeting'),topic:'small-talk',grounded:true};if(/^(good morning|morning|selamat pagi)( franklin)?$/.test(n))return{text:pick('morning'),topic:'small-talk',grounded:true};if(/^(good afternoon|afternoon|selamat siang|selamat sore)( franklin)?$/.test(n))return{text:pick('afternoon'),topic:'small-talk',grounded:true};if(/^(good evening|good night|evening|selamat malam)( franklin)?$/.test(n))return{text:pick('evening'),topic:'small-talk',grounded:true};if(/^(how are you|how are you doing|how you doing|you good|apa kabar|gimana kabarmu|kabar kamu gimana)$/.test(n))return{text:pick('howareyou'),topic:'small-talk',grounded:true};if(/^(thanks|thank you|thank you so much|thx|ty|makasih|makasi|terima kasih|mantap makasih|thanks bro|thanks franklin)$/.test(n))return{text:pick('thanks'),topic:'small-talk',grounded:true};if(/^(sorry|my bad|maaf|maaf ya|sorry franklin)$/.test(n))return{text:pick('sorry'),topic:'small-talk',grounded:true};if(/^(lol|lmao|wkwk|wkwkwk|haha|hahaha|hehe|😂|🤣)$/.test(n))return{text:pick('laugh'),topic:'small-talk',grounded:true};if(/^(bye|goodbye|see you|see ya|later|dadah|sampai jumpa|cabut dulu)$/.test(n))return{text:pick('bye'),topic:'small-talk',grounded:true};if(/\b(who are you|who is franklin|what are you|siapa kamu|kamu siapa|ini siapa)\b/.test(n))return{text:pick('identity'),topic:'small-talk',grounded:true};if(/\b(what can you do|what can you answer|what do you know|apa yang bisa kamu lakukan|kamu bisa apa|bisa bantu apa|bisa jawab apa)\b/.test(n))return{text:pick('capability'),topic:'small-talk',grounded:true};return null;}
function detectDevice(q){const n=norm(q);if(!state.devices?.length)return null;return state.devices.find(m=>n.includes(m._name))||null;}
function iosVersion(q){const m=String(q||'').match(/\biOS\s*(\d{1,2}(?:\.\d{1,2}){0,2})\b/i);return m?Number(m[1]):null;}
function chipClass(chip){const a=/\bA(\d{1,2})\b/i.exec(chip||''),m=/\bM(\d{1,2})\b/i.exec(chip||'');if(m)return Number(m[1])>=3?'highest documented Mac GPU class':'high Mac GPU class';if(!a)return'unverified GPU class';const g=Number(a[1]);if(g<=11)return'below the normal GPU floor';if(g===12)return'experimental A12 path';if(g===13)return'normal supported baseline';if(g===14)return'supported enhanced-effects class';if(g<=16)return'supported A15/A16 class';return'high GPU class';}
function memoryGuidance(ram){const r=Number(ram);if(!Number.isFinite(r))return'RAM is not verified in the current catalog.';if(r<4)return`${r} GB is below the project’s practical 4 GB RAM minimum.`;if(r<=4.5)return`${r} GB is in the low-memory tier: start with Normal textures, conservative resolution, MSAA off, and preserve Increased Memory Limit when eligible.`;if(r<=6.5)return`${r} GB maps to the 6 GB-class memory tier: High textures can be reasonable when the app-memory allowance also supports that tier.`;return`${r} GB provides strong physical-memory headroom; Very High textures may be possible when the app-memory allowance supports the same tier.`;}
function osGuidance(v){if(v===null)return'';if(v<16.3)return` iOS ${v} is below the audited MinimumOSVersion of 16.3.`;if(v<18)return` iOS ${v} is above the binary minimum but below the site’s current iOS 18+ recommendation.`;return` iOS ${v} meets the site’s current iOS 18+ recommendation.`;}
function deviceAnswer(q,model){const n=norm(q),v=iosVersion(q);const spec=[model.chip||'chip unverified',model.ram!=null?`${model.ram} GB RAM`:'RAM unverified',model.gpu?`${model.gpu}-core GPU`:'GPU cores unverified'].join(', ');let text=`${model.name}: ${spec}. In the project compatibility policy, ${model.chip||'this chip'} is in the ${chipClass(model.chip)}. ${memoryGuidance(model.ram)}${osGuidance(v)}`;if(/\b(best settings|setting terbaik|settings|graphics|fps|performance)\b/.test(n)){if(Number(model.ram)<=4.5)text+=' For a first stable profile, use Normal textures, low-to-moderate render resolution, MSAA off, modest shadows, and a conservative FPS cap.';else if(Number(model.ram)<=6.5)text+=' Start with High textures, moderate render resolution, MSAA off as the troubleshooting baseline, and test 30 or 40 FPS based on thermals.';else text+=' Start from a balanced profile, then raise texture and render quality one setting at a time while watching thermals and app-memory headroom.';}text+=' This is compatibility guidance, not a guaranteed FPS or certification.';return{text,topic:'device',grounded:true,knowledgeId:`device:${model.id}`,source:{href:'compatibility.html',label:'Compatibility'},suggestions:['What settings should I start with?','Why can app memory be lower than physical RAM?']};}
function chipAnswer(q){const n=norm(q);const a=n.match(/\ba(1[1-9]|20)\b/),m=n.match(/\bm([1-9])\b/);if(a){const chip=`A${a[1]}`;return{text:`${chip} is in the ${chipClass(chip)} under the project compatibility policy. Exact results still depend on the device’s RAM, iOS version, app-memory allowance, graphics settings, and thermals.`,topic:'device',grounded:true,source:{href:'compatibility.html',label:'Compatibility'}};}if(m){const chip=`M${m[1]}`;return{text:`${chip} is in the ${chipClass(chip)} under the launcher’s documented GPU grouping. For Mac, the exact build and runtime configuration still matter, so this is guidance rather than a performance guarantee.`,topic:'device',grounded:true,source:{href:'compatibility.html',label:'Compatibility'}};}return null;}
function score(e,q){const n=norm(q),qt=tokens(q);let s=0,exact=false;for(const p of e._patterns){if(!p)continue;if(n===p){s+=40;exact=true;}else if(n.length>=4&&(n.includes(p)||p.includes(n)))s+=Math.min(16,5+p.length/10);const pt=tokens(p);s+=overlap(qt,pt)*7+overlap(pt,qt)*3;}for(const t of qt){if(e._keywords.includes(t))s+=t.length>=7?4:2.8;}if(state.lastTopic&&e.topic===state.lastTopic&&raw(q).length<=7)s+=2;return{e,s,exact};}
function context(q){const n=norm(q);if(!state.lastQuestion||raw(n).length>8||!/^(and|what about|how about|then|so|why|how|where|when|kalau|terus|lalu|gimana|yang)/.test(n))return q;return`${state.lastQuestion} ${q} ${state.lastTopic}`;}
function related(topic){return({device:['What settings should I start with?','Does iRAM+ add physical RAM?'],memory:['What is app memory allowance?','Best settings for 4 GB?'],crash:['Where are the logs?','How should I report this bug?'],troubleshooting:['Where are the logs?','How do I reproduce a bug properly?'],launcher:['How do I check my build?','Should I clean reinstall?'],installation:['Will reinstall delete my save?','Why can an IPA fail to install?'],performance:['Should I use 30 or 40 FPS?','Why does FPS drop after a few minutes?'],graphics:['Should I use MetalFX?','Should I enable MSAA?'],mods:['What mod formats are supported?','What if the game crashes after a mod?'],logs:['Which logs should I send?','Is it safe to share logs?'],multiplayer:['Why does a session code fail?','Can mobile data block P2P?'],conversation:['What can you help me troubleshoot?','How should I report a bug?']}[topic]||[]);}
function applyPolicy(q,r){return window.FranklinPolicy?.post?window.FranklinPolicy.post(q,r):r;}
async function answer(rawq){const q=String(rawq||'').trim();if(!q)return null;const chat=social(q);if(chat)return chat;await load();const kind=supportKind(q);if(kind==='none')return null;const model=detectDevice(q);if(model)return deviceAnswer(q,model);const chip=chipAnswer(q);if(chip)return chip;const en=context(q),rank=(state.entries||[]).map(e=>score(e,en)).sort((a,b)=>b.s-a.s),best=rank[0],next=rank[1],qt=tokens(en);if(!best)return null;const floor=qt.length<=1?8:qt.length===2?9:Math.min(14,6+qt.length*.85);const margin=next?best.s-next.s:best.s;if(!best.exact&&(best.s<floor||margin<.7&&best.s<15))return null;state.lastQuestion=q;state.lastTopic=best.e.topic||'';return{text:best.e.answer,topic:best.e.topic||'support',grounded:true,knowledgeId:best.e.id,source:best.e.source||null,suggestions:best.e.suggestions||related(best.e.topic)};}
function wrapConversation(){const api=window.FranklinConversation;if(!api||api.__generalSupportSocialWrapped)return false;const old=api.social?.bind(api);api.social=q=>social(q)||old?.(q)||null;api.__generalSupportSocialWrapped=true;return true;}
function wrapSite(){const api=window.FranklinSiteRAG;if(!api||api.__generalSupportWrapped||typeof api.answer!=='function')return false;const old=api.answer.bind(api);api.answer=async q=>{const chat=social(q);if(chat)return applyPolicy(q,chat);const kind=supportKind(q);if(kind==='bug')return null;if(kind==='device'||kind==='support'||kind==='followup'){const g=await answer(q);if(g)return applyPolicy(q,g);}return old(q);};api.__generalSupportWrapped=true;return true;}
function wrapExtended(){const api=window.FranklinExtended;if(!api||api.__generalSupportWrapped||typeof api.answer!=='function')return false;const old=api.answer.bind(api);api.answer=async q=>{const chat=social(q);if(chat)return applyPolicy(q,chat);const kind=supportKind(q);if(kind!=='bug'&&kind!=='none'){const g=await answer(q);if(g)return applyPolicy(q,g);}const base=await old(q);if(kind==='bug'&&(!base?.knowledgeId||base.topic==='developer-triage'||base.topic==='unknown'||base.topic==='off-topic')){const g=await answer(q);if(g)return applyPolicy(q,g);}if(base)return base;const g=await answer(q);return g?applyPolicy(q,g):base;};api.__generalSupportWrapped=true;return true;}
function wrapEngine(){const api=window.FranklinEngine;if(!api||api.__generalSupportWrapped||typeof api.answer!=='function')return false;const old=api.answer.bind(api);api.answer=async q=>{const kind=supportKind(q);if(kind!=='none'){const g=await answer(q);if(g)return applyPolicy(q,g);}return old(q);};api.__generalSupportWrapped=true;return true;}
function reset(){state.lastQuestion='';state.lastTopic='';state.socialTurn=0;}
document.addEventListener('franklin-disconnect',reset);
let tries=0;const timer=setInterval(()=>{wrapConversation();wrapSite();wrapExtended();wrapEngine();if(++tries>120)clearInterval(timer)},50);
